%% 动态BMI分组与最佳孕期检测时间节点优化算法
% 基于风险函数的多目标优化

clear all;
clc;
close all;

%% 加载数据（假设已经运行了前面的代码创建了数据矩阵）
% 如果没有数据，请先运行前面的数据创建代码
if ~exist('pregnancy_data_matrix', 'var')
    % 重新加载数据（这里简化处理，实际使用时请确保数据已加载）
    fprintf('正在加载数据...\n');
    % 这里应该包含您之前的数据，为了代码完整性，我会重新定义关键变量
    load('pregnancy_data.mat'); % 假设数据已保存
end

% 提取数据
BMI = pregnancy_data_matrix(:, 1);
gestational_weeks = pregnancy_data_matrix(:, 2);
Y_concentration = pregnancy_data_matrix(:, 3);

%% 参数设置
alpha = 0.7; % 风险函数参数，可调节（0.6-0.8范围）
threshold_c = 0.04; % Y染色体浓度阈值
n_groups = 5; % 分组数量
max_iterations = 100; % 最大迭代次数

%% 主要优化函数
fprintf('=== 开始动态BMI分组与最佳检测时间优化 ===\n\n');

% 获取BMI范围
BMI_min = min(BMI);
BMI_max = max(BMI);
gestational_min = min(gestational_weeks);
gestational_max = max(gestational_weeks);

fprintf('数据范围:\n');
fprintf('BMI: %.2f - %.2f\n', BMI_min, BMI_max);
fprintf('孕周: %.2f - %.2f\n', gestational_min, gestational_max);
fprintf('样本总数: %d\n\n', length(BMI));

%% 动态分组优化
best_overall_risk = inf;
best_grouping = [];
best_optimal_weeks = [];
best_group_risks = [];
best_group_info = [];

% 定义分组搜索策略
n_search_points = 20; % 每个分组点的搜索密度
BMI_range = BMI_max - BMI_min;
step_size = BMI_range / (n_search_points * (n_groups - 1));

fprintf('开始分组优化搜索...\n');
fprintf('搜索空间大小: %d^%d = %.0f 种组合\n', n_search_points, n_groups-1, n_search_points^(n_groups-1));

iteration = 0;
total_combinations = n_search_points^(n_groups-1);

% 生成所有可能的分组组合
for iter = 1:min(max_iterations, 1000) % 限制搜索次数以提高效率
    iteration = iteration + 1;
    
    % 生成随机分组点（确保递增顺序）
    group_boundaries = sort(BMI_min + rand(1, n_groups-1) * BMI_range);
    group_boundaries = [BMI_min, group_boundaries, BMI_max];
    
    % 确保分组点之间有足够间距
    min_gap = BMI_range / (n_groups * 2);
    valid_grouping = true;
    for i = 1:length(group_boundaries)-1
        if group_boundaries(i+1) - group_boundaries(i) < min_gap
            valid_grouping = false;
            break;
        end
    end
    
    if ~valid_grouping
        continue;
    end
    
    % 评估当前分组
    [group_risks, optimal_weeks, group_info] = evaluate_grouping(BMI, gestational_weeks, Y_concentration, group_boundaries, alpha, threshold_c);
    
    % 计算总体风险（所有组的加权平均风险）
    group_sizes = cellfun(@length, {group_info.indices});
    if any(group_sizes == 0) % 跳过空组
        continue;
    end
    
    weights = group_sizes / sum(group_sizes);
    overall_risk = sum(group_risks .* weights);
    
    % 更新最佳结果
    if overall_risk < best_overall_risk
        best_overall_risk = overall_risk;
        best_grouping = group_boundaries;
        best_optimal_weeks = optimal_weeks;
        best_group_risks = group_risks;
        best_group_info = group_info;
        
        fprintf('迭代 %d: 发现更优解，总体风险 = %.6f\n', iteration, overall_risk);
    end
    
    % 显示进度
    if mod(iteration, 50) == 0
        fprintf('进度: %d/%d, 当前最佳风险: %.6f\n', iteration, max_iterations, best_overall_risk);
    end
end

%% 显示最终结果
fprintf('\n=== 优化结果 ===\n');
fprintf('最佳总体风险值: %.6f\n', best_overall_risk);
fprintf('最佳分组边界: ');
for i = 1:length(best_grouping)
    fprintf('%.2f ', best_grouping(i));
end
fprintf('\n\n');

fprintf('各组详细信息:\n');
fprintf('%s\n', repmat('-', 1, 80));
fprintf('%-8s %-20s %-12s %-15s %-12s %-10s\n', '组别', 'BMI范围', '样本数', '最佳孕周', '风险值', '精度');
fprintf('%s\n', repmat('-', 1, 80));

for i = 1:length(best_group_risks)
    if ~isempty(best_group_info(i).indices)
        bmi_range = sprintf('[%.1f-%.1f)', best_grouping(i), best_grouping(i+1));
        sample_count = length(best_group_info(i).indices);
        optimal_week = best_optimal_weeks(i);
        risk_value = best_group_risks(i);
        precision = best_group_info(i).precision;
        
        fprintf('%-8d %-20s %-12d %-15.2f %-12.6f %-10.4f\n', ...
                i, bmi_range, sample_count, optimal_week, risk_value, precision);
    end
end

%% 创建可视化图表
create_visualization(BMI, gestational_weeks, Y_concentration, best_grouping, best_optimal_weeks, best_group_info, threshold_c);

%% 保存结果
results = struct();
results.best_overall_risk = best_overall_risk;
results.best_grouping = best_grouping;
results.best_optimal_weeks = best_optimal_weeks;
results.best_group_risks = best_group_risks;
results.best_group_info = best_group_info;
results.alpha = alpha;
results.threshold_c = threshold_c;

