%% 辅助函数

function [group_risks, optimal_weeks, group_info] = evaluate_grouping(BMI, gestational_weeks, Y_concentration, group_boundaries, alpha, threshold_c)
    % 评估给定分组的风险和最佳检测时间
    
    n_groups = length(group_boundaries) - 1;
    group_risks = zeros(1, n_groups);
    optimal_weeks = zeros(1, n_groups);
    group_info = struct('indices', {}, 'precision', {}, 'sample_data', {});
    
    for g = 1:n_groups
        % 找到属于当前组的样本
        if g == n_groups
            group_mask = BMI >= group_boundaries(g) & BMI <= group_boundaries(g+1);
        else
            group_mask = BMI >= group_boundaries(g) & BMI < group_boundaries(g+1);
        end
        
        group_indices = find(group_mask);
        
        if isempty(group_indices)
            group_risks(g) = inf;
            optimal_weeks(g) = NaN;
            group_info(g).indices = [];
            group_info(g).precision = 0;
            group_info(g).sample_data = [];
            continue;
        end
        
        % 提取组内数据
        group_gestational = gestational_weeks(group_indices);
        group_Y = Y_concentration(group_indices);
        
        % 寻找最佳检测时间点
        week_candidates = linspace(min(group_gestational), max(group_gestational), 20);
        min_risk = inf;
        best_week = NaN;
        best_precision = 0;
        
        for week = week_candidates
            % 计算在该时间点之后的样本精度
            later_samples_mask = group_gestational >= week;
            if sum(later_samples_mask) == 0
                continue;
            end
            
            later_Y = group_Y(later_samples_mask);
            precision = sum(later_Y > threshold_c) / length(later_Y);
            
            % 计算风险函数
            week_min = min(group_gestational);
            week_max = max(group_gestational);
            
            if week_max == week_min
                normalized_week = 0.5;
            else
                normalized_week = (week - week_min) / (week_max - week_min);
            end
            
            % 实用准则风险函数
            risk = alpha * (1 - precision) + (1 - alpha) * normalized_week;
            
            if risk < min_risk
                min_risk = risk;
                best_week = week;
                best_precision = precision;
            end
        end
        
        group_risks(g) = min_risk;
        optimal_weeks(g) = best_week;
        group_info(g).indices = group_indices;
        group_info(g).precision = best_precision;
        group_info(g).sample_data = [group_gestational, group_Y];
    end
end

function create_visualization(BMI, gestational_weeks, Y_concentration, best_grouping, best_optimal_weeks, best_group_info, threshold_c)
    % 创建综合可视化图表
    
    figure('Name', 'BMI分组优化结果', 'Position', [50, 50, 1400, 1000]);
    
    % 定义颜色
    colors = lines(length(best_grouping)-1);
    
    % 子图1: BMI分组可视化
    subplot(2, 3, 1);
    hold on;
    for i = 1:length(best_group_info)
        if ~isempty(best_group_info(i).indices)
            group_BMI = BMI(best_group_info(i).indices);
            scatter(group_BMI, i*ones(size(group_BMI)), 50, colors(i,:), 'filled', 'MarkerFaceAlpha', 0.6);
        end
    end
    
    % 绘制分组边界
    for i = 2:length(best_grouping)-1
        xline(best_grouping(i), '--k', 'LineWidth', 2);
    end
    
    xlabel('BMI');
    ylabel('组别');
    title('BMI分组结果');
    grid on;
    legend(arrayfun(@(x) sprintf('组%d', x), 1:length(best_group_info), 'UniformOutput', false), 'Location', 'best');
    
    % 子图2: 每组的最佳检测时间
    subplot(2, 3, 2);
    bar(1:length(best_optimal_weeks), best_optimal_weeks, 'FaceColor', [0.3, 0.6, 0.8]);
    xlabel('组别');
    ylabel('最佳检测孕周');
    title('各组最佳检测时间');
    grid on;
    
    % 子图3: 每组的风险值
    subplot(2, 3, 3);
    bar(1:length(best_group_info), [best_group_info.precision], 'FaceColor', [0.8, 0.4, 0.2]);
    xlabel('组别');
    ylabel('精度 P(c>0.04)');
    title('各组检测精度');
    grid on;
    
    % 子图4: 散点图 - BMI vs 孕周，按组着色
    subplot(2, 3, 4);
    hold on;
    for i = 1:length(best_group_info)
        if ~isempty(best_group_info(i).indices)
            group_indices = best_group_info(i).indices;
            scatter(BMI(group_indices), gestational_weeks(group_indices), 30, colors(i,:), 'filled', 'MarkerFaceAlpha', 0.6);
            
            % 标记最佳检测时间
            if ~isnan(best_optimal_weeks(i))
                yline(best_optimal_weeks(i), '--', 'Color', colors(i,:), 'LineWidth', 2);
            end
        end
    end
    xlabel('BMI');
    ylabel('孕周');
    title('BMI vs 孕周 (按组着色)');
    grid on;
    
    % 子图5: Y染色体浓度分布
    subplot(2, 3, 5);
    hold on;
    for i = 1:length(best_group_info)
        if ~isempty(best_group_info(i).indices)
            group_indices = best_group_info(i).indices;
            histogram(Y_concentration(group_indices), 15, 'FaceColor', colors(i,:), 'FaceAlpha', 0.6, 'EdgeColor', 'none');
        end
    end
    xline(threshold_c, '--r', 'LineWidth', 2, 'DisplayName', sprintf('阈值=%.2f', threshold_c));
    xlabel('Y染色体浓度');
    ylabel('频数');
    title('各组Y染色体浓度分布');
    legend('show');
    grid on;
    
    % 子图6: 风险函数可视化
    subplot(2, 3, 6);
    group_numbers = 1:length(best_group_info);
    group_risks = zeros(size(group_numbers));
    for i = 1:length(best_group_info)
        if ~isempty(best_group_info(i).indices)
            % 重新计算风险值用于显示
            precision = best_group_info(i).precision;
            week_min = min(gestational_weeks(best_group_info(i).indices));
            week_max = max(gestational_weeks(best_group_info(i).indices));
            if week_max == week_min
                normalized_week = 0.5;
            else
                normalized_week = (best_optimal_weeks(i) - week_min) / (week_max - week_min);
            end
            group_risks(i) = 0.7 * (1 - precision) + 0.3 * normalized_week;
        else
            group_risks(i) = NaN;
        end
    end
    
    bar(group_numbers, group_risks, 'FaceColor', [0.6, 0.3, 0.7]);
    xlabel('组别');
    ylabel('风险值');
    title('各组风险评估');
    grid on;
    
    sgtitle('BMI动态分组与最佳检测时间优化结果', 'FontSize', 16, 'FontWeight', 'bold');
end




%% 绘制函数（放在文件最后）
function plot_risk_curves_for_best_grouping(BMI, gestational_weeks, Y_concentration, best_grouping, best_optimal_weeks, alpha, threshold_c)
    % 绘制最佳分组方式下各组的风险值折线图
    
    n_groups = length(best_grouping) - 1;
    colors = lines(n_groups);
    
    figure('Name', 'Time-Accuracy Tradeoff: Risk vs Week (BMI Groups)', 'Position', [100, 100, 1200, 800]);
    hold on;
    
    legend_entries = {};
    
    for g = 1:n_groups
        % 找到属于当前组的样本
        if g == n_groups
            group_mask = BMI >= best_grouping(g) & BMI <= best_grouping(g+1);
        else
            group_mask = BMI >= best_grouping(g) & BMI < best_grouping(g+1);
        end
        
        group_indices = find(group_mask);
        
        if isempty(group_indices)
            continue;
        end
        
        % 提取组内数据
        group_gestational = gestational_weeks(group_indices);
        group_Y = Y_concentration(group_indices);
        
        % 定义时间节点范围
        week_min = min(group_gestational);
        week_max = max(group_gestational);
        
        % 生成时间节点用于绘制曲线
        time_points = linspace(week_min, week_max, 30);
        risk_values = zeros(size(time_points));
        
        % 计算每个时间节点的风险值
        for t = 1:length(time_points)
            week = time_points(t);
            
            % 计算在该时间点之后的样本精度
            later_samples_mask = group_gestational >= week;
            
            if sum(later_samples_mask) == 0
                precision = 0;
            else
                later_Y = group_Y(later_samples_mask);
                precision = sum(later_Y > threshold_c) / length(later_Y);
            end
            
            % 计算标准化时间
            if week_max == week_min
                normalized_week = 0.5;
            else
                normalized_week = (week - week_min) / (week_max - week_min);
            end
            
            % 计算风险函数值
            risk_values(t) = alpha * (1 - precision) + (1 - alpha) * normalized_week;
        end
        
        % 绘制风险曲线
        plot(time_points, risk_values, 'LineWidth', 2.5, 'Color', colors(g,:));
        
        % 标记最优点
        if ~isnan(best_optimal_weeks(g))
            % 找到最优点对应的风险值
            [~, optimal_idx] = min(abs(time_points - best_optimal_weeks(g)));
            scatter(best_optimal_weeks(g), risk_values(optimal_idx), 100, colors(g,:), ...
                    'filled', 'MarkerEdgeColor', 'black', 'LineWidth', 2);
            
            % 添加最优点标注
            text(best_optimal_weeks(g), risk_values(optimal_idx) + 0.02, ...
                 sprintf('%.1f周', best_optimal_weeks(g)), ...
                 'HorizontalAlignment', 'center', 'FontSize', 10, 'FontWeight', 'bold', ...
                 'Color', colors(g,:));
        end
        
        % 准备图例
        sample_count = length(group_indices);
        legend_entries{end+1} = sprintf('组%d: BMI[%.1f-%.1f] (n=%d)', ...
                                       g, best_grouping(g), best_grouping(g+1), sample_count);
    end
    
    % 设置图表属性
    xlabel('检测孕周 (Week)', 'FontSize', 14, 'FontWeight', 'bold');
    ylabel('风险值 Risk(w)', 'FontSize', 14, 'FontWeight', 'bold');
    title(sprintf('Time-Accuracy Tradeoff: Risk vs Week (5 BMI Groups)\nα=%.1f, 阈值=%.3f', alpha, threshold_c), ...
          'FontSize', 16, 'FontWeight', 'bold');
    
    % 添加图例
    legend(legend_entries, 'Location', 'best', 'FontSize', 11);
    
    % 设置网格和坐标轴
    grid on;
    grid minor;
    set(gca, 'FontSize', 12);
    
    % 添加说明文字
    text(0.02, 0.98, sprintf('风险函数: R(w) = α(1-P(c>%.3f)) + (1-α)·标准化时间', threshold_c), ...
         'Units', 'normalized', 'VerticalAlignment', 'top', 'FontSize', 10, ...
         'BackgroundColor', 'white', 'EdgeColor', 'black');
    
    hold off;
    
    % 显示各组信息
    fprintf('各组风险曲线信息:\n');
    fprintf('%-6s %-20s %-12s %-15s\n', '组别', 'BMI范围', '样本数', '最佳检测时间');
    fprintf('%s\n', repmat('-', 1, 60));
    
    for g = 1:n_groups
        if g == n_groups
            group_mask = BMI >= best_grouping(g) & BMI <= best_grouping(g+1);
        else
            group_mask = BMI >= best_grouping(g) & BMI < best_grouping(g+1);
        end
        
        sample_count = sum(group_mask);
        if sample_count > 0
            fprintf('%-6d %-20s %-12d %-15.2f\n', ...
                    g, sprintf('[%.1f-%.1f]', best_grouping(g), best_grouping(g+1)), ...
                    sample_count, best_optimal_weeks(g));
        end
    end
    
    fprintf('\n图表已生成：Time-Accuracy Tradeoff: Risk vs Week (5 BMI Groups)\n');
end


